import React, { useState } from 'react';
import StarBackground from './StarBackground';
import { sendAuthOtp, verifyAuthOtp, resetUserPassword } from '../../services/dbService';

interface LandingPageProps {
  onSeekerEnter: () => void;
  onSeekerLogin: (verifiedContact: string) => void;
  onVerifyCredentials: (contact: string, password: string) => Promise<boolean>;
  onGuruEnter: () => void;
  onAdminEnter: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSeekerEnter, onSeekerLogin, onVerifyCredentials, onGuruEnter, onAdminEnter }) => {
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginStep, setLoginStep] = useState<'credentials' | 'otp' | 'forgot_request' | 'forgot_otp' | 'forgot_new_password'>('credentials');

  // Credentials & State (re-used from previous, ensuring logic is intact)
  const [phoneNumber, setPhoneNumber] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [otp, setOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [isAdminMode, setIsAdminMode] = useState(false);
  const [adminPin, setAdminPin] = useState('');

  // Handlers (Exact same logic as previous implementation for security)
  const handleCredentialsSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if(isAdminMode) { if(adminPin==='1609') onAdminEnter(); else setErrorMsg("Invalid PIN"); return; }
    if(phoneNumber.toLowerCase() === 'admin') { setIsAdminMode(true); return; }
    setIsLoading(true);
    try {
        const isValid = await onVerifyCredentials(phoneNumber, password);
        if(isValid) { 
            const res = await sendAuthOtp(phoneNumber); 
            if(res.success || res.isRateLimit) setLoginStep('otp'); 
            else setErrorMsg(res.message || "Failed"); 
        } else setErrorMsg("Invalid Credentials");
    } catch(e) { setErrorMsg("Error"); } finally { setIsLoading(false); }
  };

  const handleOtpSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setIsLoading(true);
      try {
          const res = await verifyAuthOtp(phoneNumber, otp);
          if(res.success) onSeekerLogin(phoneNumber); else setErrorMsg("Invalid OTP");
      } catch(e) { setErrorMsg("Error"); } finally { setIsLoading(false); }
  };

  // UI Components
  const FeatureCard = ({ icon, title, desc }: { icon: string, title: string, desc: string }) => (
