                <div className="relative z-10">
                    <h3 className="text-2xl font-serif font-bold text-white mb-2 group-hover:text-gold-300">Start Journey</h3>
                    <p className="text-mystic-400 text-sm">Consult AI, get Vastu blueprints & daily insights.</p>
