          generateDailyHoroscope();
      }
  }, [view, userState.hasOnboarded]);

  const generateDailyHoroscope = async () => {
      setIsGeneratingHoroscope(true);
      try {
          const prompt = `Generate a JSON object for Daily Horoscope for ${userState.name} (${userState.birthDate}). 
          Format: { "overview": "string", "dos": ["string", "string"], "donts": ["string", "string"], "luckyColor": "string", "luckyNumber": "string" }. 
          Keep it short and spiritual.`;

          // Note: In real app, we'd use responseMimeType: 'application/json' in genai config, 
          // here we just parse the text text response aggressively
          const response = await sendMessageToGemini(prompt);

          // Simple heuristic parser if AI returns markdown json
          const jsonMatch = response.match(/\{[\s\S]*\}/);
          if (jsonMatch) {
              const data = JSON.parse(jsonMatch[0]);
              setHoroscopeData(data);
          } else {
              // Fallback
              setHoroscopeData({
                  overview: response.substring(0, 100) + "...",
