                  luckyColor: "Orange",
                  luckyNumber: "9"
              });
          }
      } catch (e) {
          console.error("Horoscope Gen Failed", e);
      } finally {
          setIsGeneratingHoroscope(false);
      }
  };

  const handleSendYearlyReport = () => {
      if(!userState.isPremium) {
          setPremiumModalReason("Yearly Reports are for Premium Members only.");
          setShowPremiumModal(true);
          return;
      }
      logCommunication('email', userState.contact || 'User', 'outbound', 'sent', 'Yearly Report 2024');
      alert(`Yearly Report has been emailed to you!`);
  };

  // --- SAVE PROFILE ---
  useEffect(() => {
      const saveToDb = async () => { if (userState.hasOnboarded && userState.contact) await saveUserProfile(userState, undefined, messages); };
      const timer = setTimeout(saveToDb, 2000); 
      return () => clearTimeout(timer);
  }, [userState, messages]);

  // Session Timer
  useEffect(() => {
    if (!sessionExpiry || !userState.connectedAstrologerId) { setTimeLeft(''); return; }
    const interval = setInterval(() => {
