        if (diff <= 0) { clearInterval(interval); disconnectAstrologer(); setMessages(prev => [...prev, { id: generateId(), text: "System: Your 10-minute session has ended. Please reconnect to continue.", sender: Sender.SYSTEM, timestamp: new Date() }]); }
        else { const mins = Math.floor(diff / 60000); const secs = Math.floor((diff % 60000) / 1000); setTimeLeft(`${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`); }
    }, 1000);
    return () => clearInterval(interval);
  }, [sessionExpiry, userState.connectedAstrologerId]);

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages, isLoading, view]);

  // ... (Keep existing helpers: updateEarnings, addTransaction, handleUpdateProducts, findRelevantProducts, initiatePayment, proceedToRazorpay, initiateProductPurchase, confirmPurchaseWithAddress, verifyUserCredentials, handleSeekerLogin, handleGuruEnter, finalizeOnboarding, handleOnboardingSubmit, start/stopRecording, handleSendMessage, handleUnlockMessage, handleGuruDakshina, connectToAstrologer, disconnectAstrologer, handleRateGuru, handleAcceptCall, handleAstrologerAction, handleCallEnd, openHistory) ...
  // Re-implementing essential logic for context in XML

  const handleSendMessage = async (overrideText?: string) => {
    const textToSend = overrideText || input;
    if (!textToSend.trim() || isLoading) return;
    if (userState.connectedAstrologerId) { setMessages(prev => [...prev, { id: generateId(), text: textToSend, sender: Sender.USER, timestamp: new Date() }]); setInput(''); return; }
    if (userState.dailyQuestionsLeft <= 0) { setPremiumModalReason('Daily question limit reached.'); setShowPremiumModal(true); return; }
    setMessages(prev => [...prev, { id: generateId(), text: textToSend, sender: Sender.USER, timestamp: new Date() }]); setInput(''); setIsLoading(true);
    try {
      const now = new Date().toLocaleString();
      const prompt = `[Time: ${now}] ${userState.language === 'hi' ? "(REPLY IN HINDI)" : ""} ${textToSend}`;
      const responseText = await sendMessageToGemini(prompt);
      const hasDeepDive = responseText.includes("Deep Dive:");
      const suggestedProducts = findRelevantProducts(responseText);
      setMessages(prev => [...prev, { id: generateId(), text: responseText, sender: Sender.AI, timestamp: new Date(), isLocked: hasDeepDive && !userState.isPremium, suggestedProducts: suggestedProducts.length > 0 ? suggestedProducts : undefined }]);
      setUserState(prev => ({ ...prev, dailyQuestionsLeft: prev.dailyQuestionsLeft - 1 }));
    } catch (error) { setMessages(prev => [...prev, { id: generateId(), text: "Connection clouded.", sender: Sender.AI, timestamp: new Date() }]); } finally { setIsLoading(false); }
  };

  const findRelevantProducts = (text: string): Product[] => {
      const lowerText = text.toLowerCase();
      return products.filter(p => p.name.toLowerCase().split(' ').some(word => word.length > 4 && lowerText.includes(word))).slice(0, 1);
  };

  const handleSeekerEnter = () => setHasStarted(true);
