  const handleSeekerLogin = async (contact: string) => {
      setHasStarted(true); setIsLoading(true);
      try {
          const clean = contact.trim();
          const vars = [clean]; if(!clean.includes('+')) vars.push(`+91 ${clean}`, `+91${clean}`); if(clean.includes(' ')) vars.push(clean.replace(/\s/g,''));
          const { profile, chatHistory } = await fetchUserProfile(vars);
          if (profile) {
